export async function restoreOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(restorePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();
  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** All expired deletions, independently of usage rows or job batch limits. */
export async function listOrgsDeletedBefore(cutoff: IsoTimestamp): Promise<readonly Organization[]> {
  return getDb().select().from(organizations)
    .where(lte(organizations.archivedAt, cutoff))
    .all().map(toOrganization);
}

/** Deletes the whole tenant atomically, while preserving global accounts and sessions. */
export async function purgeDeletedOrg(orgId: OrgId, cutoff: IsoTimestamp): Promise<boolean> {
  return getDb().transaction((tx) => {
    const expired = tx.select({ id: organizations.id }).from(organizations)
      .where(and(eq(organizations.id, orgId), lte(organizations.archivedAt, cutoff))).get();
    if (!expired) return false;

    const tenantTables = [
      issueLabels, projectMembers, attachments, comments, notifications,
      notificationPreferences, activityEvents, webhookDeliveries, webhookEndpoints,
      searchIndex, rateLimitBuckets, invoices, subscriptions, issues, labels,
      projects, invitations, members, organizationUsage,
    ];
    for (const table of tenantTables) {
      tx.delete(table).where(eq(table.orgId, orgId)).run();
    }
    tx.update(sessions).set({ activeOrgId: null })
      .where(eq(sessions.activeOrgId, orgId)).run();
    tx.delete(organizations).where(eq(organizations.id, orgId)).run();
    return true;
  });
}
